  heros: (F, c) => { const k = c.costumeC != null ? (AV2.accC[c.costumeC] || c.costumeC) : '#D63A3A'; return { outfit: 'jumpsuit', outfitC: k, shoes: 'boots', shoesC: k, _sleeve: 100, _sleeveC: k, pose: c.pose === 'pocket' ? 'hip' : c.pose }; },
  vampire: F => F ? { outfit: 'none', top: 'blouse', topC: '#141416', bottom: 'maxi', bottomC: '#5E0B18', shoes: 'boots', shoesC: '#141416', lips: 'rouge' }
    : { outfit: 'none', top: 'shirt', topC: '#F4F1EA', bottom: 'chinos', bottomC: '#141416', shoes: 'loafers', shoesC: '#141416' },
