  pirate: F => F ? { outfit: 'none', top: 'blouse', topC: '#F4F1EA', bottom: 'skirt', bottomC: '#4A3020', shoes: 'boots', shoesC: '#5A3A22', _hatOn: 1, jewel: ['hoops'] }
    : { outfit: 'none', top: 'blouse', topC: '#F4F1EA', bottom: 'chinos', bottomC: '#2B2B33', shoes: 'boots', shoesC: '#5A3A22', tuck: true, _hatOn: 1, jewel: ['hoops'] },
